const s = $('Settings Loader').first().json;
const render = (tpl, vars) => tpl.replace(/\{\{(\w+)\}\}/g, (_, k) => (vars[k] !== undefined && vars[k] !== null) ? vars[k] : '');
const appts = $input.all().map(i => i.json);
const toNotify = [];
for (const a of appts) {
  const status = String(a['Status'] || '').trim();
  if (status !== 'Scheduled') continue;
  const apptDate = String(a['Appt Date'] || '').trim();
  const apptTime = String(a['Appt Time'] || '').trim();
  const notifiedDate = String(a['Notified Appt Date'] || '').trim();
  const notifiedTime = String(a['Notified Appt Time'] || '').trim();
  if (!apptDate || !apptTime) continue;
  const dateChanged = apptDate !== notifiedDate;
  const timeChanged = apptTime.toUpperCase() !== notifiedTime.toUpperCase();
  if (!dateChanged && !timeChanged) continue;
  const phone = String(a['Phone'] || '').trim();
  if (!phone) continue;
  const raw = phone.replace(/\D/g, '');
  const e164 = raw.length === 11 && raw.startsWith('1') ? '+' + raw : raw.length === 10 ? '+1' + raw : (phone.startsWith('+') ? phone : null);
  if (!e164) continue;
  let displayDate = apptDate;
  try { const dm = apptDate.split('-').map(Number); const dt = DateTime.fromObject({ year: dm[0], month: dm[1], day: dm[2] }, { zone: s.timezone }); displayDate = dt.toFormat('cccc, LLLL d'); } catch (e) {}
  const nameParts = String(a['Customer Name'] || '').trim().split(/\s+/);
  const firstName = nameParts[0] || '';
  const fullName = String(a['Customer Name'] || '').trim();
  const svc = String(a['Service Type'] || s.appointment_term || 'appointment').trim();
  const tpl = s.sms_template_reschedule_update || 'Hi {{firstName}}, your {{service}} appointment with {{businessName}} has been updated to {{date}} at {{time}}. Questions? Call {{businessPhoneDisplay}}.';
  const smsBody = render(tpl, { firstName, fullName, service: svc, appointmentTerm: s.appointment_term || 'appointment', businessName: s.business_name, businessPhoneDisplay: s.business_phone_display || '', date: displayDate, time: apptTime });
  toNotify.push({ apptId: a['Appt ID'], leadId: a['Lead ID'] || '', customerName: fullName, customerPhone: e164, smsBody, newApptDate: apptDate, newApptTime: apptTime, from: s.twilio_from_number });
}
if (toNotify.length === 0) return [];
return toNotify.map(r => ({ json: r }));
